type Direction = "north" | "south" | "east" | "west";

type Position = {
  x: number;
  y: number;
};

function move(from: Position, direction: Direction): Position {
  switch (direction) {
    case "north":
      return { x: from.x, y: from.y + 1 };
    case "south":
      return { x: from.x, y: from.y - 1 };
    case "east":
      return { x: from.x + 1, y: from.y };
    case "west":
      return { x: from.x - 1, y: from.y };
  }
}

let position: Position = { x: 0, y: 0 };
const route: Direction[] = ["north", "north", "east", "south", "west", "west"];

for (const direction of route) {
  position = move(position, direction);
  console.log(`${direction} -> (${position.x}, ${position.y})`);
}

