practice.solution:
export type Light = "red" | "yellow" | "green";

export function next(light: Light): Light {
  switch (light) {
    case "red":
      return "green";
    case "green":
      return "yellow";
    case "yellow":
      return "red";
  }
}

let light: Light = "red";
for (let step = 0; step < 4; step++) {
  const after = next(light);
  console.log(`${light} -> ${after}`);
  light = after;
}

