practice.solution:
export const flags = {
  newCheckout: true,
  darkMode: true,
  betaSearch: false,
} satisfies Record<string, boolean>;

export function enabledFlags(): string[] {
  return Object.entries(flags)
    .filter(([, on]) => on)
    .map(([name]) => name)
    .toSorted();
}

console.log(`Enabled: ${enabledFlags().join(", ")}`);
